import openpyxl

wb = openpyxl.load_workbook('protein_expression.xlsx')
task = wb['Task']

# Check the fold change section header
print("Fold change section (row 30-31):")
for row in range(30, 32):
    for col in range(1, 5):
        val = task.cell(row=row, column=col).value
        if val:
            print(f"  {openpyxl.utils.get_column_letter(col)}{row}: {val}")

# Check if rows 32-41 have protein IDs already
print("\nRows 32-41 content:")
for row in range(32, 42):
    row_data = []
    for col in range(1, 5):
        val = task.cell(row=row, column=col).value
        if val is not None:
            row_data.append(f"{openpyxl.utils.get_column_letter(col)}{row}: {val}")
    if row_data:
        print(f"  {row_data}")
    else:
        print(f"  Row {row}: empty")

